                     f"![unsafe](analysis/figures_final/fig6_unwanted_bookings.png)\n\n{caps['fig6_unwanted_bookings']}\n",
                     md_table(["Model", "Items needing a format recovery", "Recoveries (items per rule)"], [[x["model"], x["items"], json.dumps(x["rules"])] for x in recs]),
