                     md_table(["Model", "Discarded replies (total)"] + [D.LANG_NAME[l] for l in D.LANGS], [[D.DISPLAY[r.key], sum(disc_lang[r.key].values())] + [disc_lang[r.key].get(l, 0) for l in D.LANGS] for r in rs]),
